"use client";
import { useEffect, useState } from "react";
import { generateModel, parameterCount, connectionCount, neuronCount, ENGINE_VERSION } from "@neuron/engine";
import { HERO_CONFIG } from "@/lib/client/specimens";

/**
 * First-visit sequence. Everything it shows is computed live: the hero specimen is generated by
 * the real engine and its artifact hash resolves digit by digit.
 */
export function BootLoader() {
  const [state, setState] = useState<"boot" | "out" | "done">("done");
  const [facts, setFacts] = useState<{ neurons: number; edges: number; params: number; ms: string; hash: string } | null>(null);
  const [shown, setShown] = useState(0);
  useEffect(() => {
    let seen = false;
    try { seen = sessionStorage.getItem("neuron.booted") === "1"; sessionStorage.setItem("neuron.booted", "1"); } catch { /* ignore */ }
    if (seen || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    setState("boot");
    const t0 = performance.now();
    const m = generateModel(HERO_CONFIG);
    setFacts({ neurons: neuronCount(m), edges: connectionCount(m), params: parameterCount(m), ms: (performance.now() - t0).toFixed(1), hash: m.artifactHash });
    const out = setTimeout(() => setState("out"), 2300);
    const skip = () => setState("out");
    window.addEventListener("keydown", skip, { once: true });
    return () => { clearTimeout(out); window.removeEventListener("keydown", skip); };
  }, []);
  useEffect(() => {
    if (!facts) return;
    const t = setInterval(() => setShown((s) => (s >= 64 ? (clearInterval(t), 64) : s + 2)), 22);
    return () => clearInterval(t);
  }, [facts]);
  useEffect(() => { if (state === "out") { const t = setTimeout(() => setState("done"), 900); return () => clearTimeout(t); } }, [state]);
  if (state === "done") return null;
  const glyphs = "0123456789abcdef";
  return (
    <div aria-hidden onClick={() => setState("out")}
      className={`fixed inset-0 z-[100] flex items-center justify-center bg-bg transition-[opacity,filter] duration-[900ms] ease-[cubic-bezier(.7,0,.2,1)] ${state === "out" ? "pointer-events-none opacity-0 blur-md" : "opacity-100"}`}>
      <div className="pointer-events-none absolute left-1/2 top-1/2 h-[520px] w-[520px] -translate-x-1/2 -translate-y-1/2 rounded-full bg-accent/10 blur-[120px]" />
      <div className="relative w-[min(560px,calc(100vw-40px))] text-center">
        <div className="rise font-serif-d text-[72px] font-light leading-none tracking-[-0.03em] sm:text-[96px]">Neuron</div>
        <div className="rise mx-auto mt-8 h-px w-48 overflow-hidden bg-line [animation-delay:.2s]"><div className="h-px bg-[linear-gradient(90deg,transparent,var(--accent-2),transparent)] transition-[width] duration-200" style={{ width: `${(shown / 64) * 100}%` }} /></div>
        {facts && (
          <div className="rise mt-8 space-y-3 [animation-delay:.35s]">
            <p className="text-[13px] text-muted">Generating specimen <span className="tnum text-fg">{HERO_CONFIG.seed}</span> · {facts.neurons} neurons · {facts.edges} connections · {facts.params} parameters · {facts.ms} ms</p>
            <p className="tnum break-all text-[12px] leading-relaxed text-faint">
              <span className="text-accent-2">{facts.hash.slice(0, shown)}</span>
              {facts.hash.slice(shown).split("").map((_, i) => glyphs[(i * 7 + shown) % 16]).join("")}
            </p>
            <p className="text-[11.5px] text-faint">{ENGINE_VERSION}</p>
          </div>
        )}
      </div>
    </div>
  );
}
